            background: white;
            border: 2px solid #333;
            box-shadow: 0 10px 30px rgba(0,0,0,0.2);
            padding: 60px 50px 40px 50px;
            position: relative;
            overflow: hidden;
        }

        .document::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background: linear-gradient(
                to bottom,
                rgba(0,0,0,0.03) 1px,
                transparent 1px
