            font-size: 22px;
            font-weight: bold;
            margin: 35px 0 15px 0;
            border-bottom: 2px solid #333;
            padding-bottom: 8px;
        }

        p {
            font-size: 16px;
            line-height: 1.6;
            margin: 12px 0;
            text-align: justify;
        }

        .centered {
            text-align: center;
            font-style: italic;
            margin: 25px 0;
        }

        .placeholder {
            width: 100%;
            height: 220px;
            background: #f0f0f0;
            border: 1px solid #aaa;
            margin: 20px 0;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 14px;
            color: #666;
            text-align: center;
            position: relative;
        }

        .placeholder::after {
            content: "CHART / DIAGRAM";
            font-weight: bold;
        }

        ul {
            margin: 15px 0 15px 30px;
            padding: 0;
        }

        li {
            font-size: 16px;
            line-height: 1.5;
            margin: 8px 0;
        }

